import React, { useState } from "react";
import { CircularProgress, Button, TextField, Typography } from "@mui/material";
import axios from "axios";

const AdForm: React.FC = () => {
  const [price, setPrice] = useState<string>("");
  const [description, setDescription] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [screenshot, setScreenshot] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault(); // Prevent form from reloading
    setLoading(true); // Set loading state
    setError(null); // Reset any previous error

    try {
      // Post data to the backend
      const response = await axios.post("http://localhost:4000/publishAd", {
        price,
        description,
      });

      // Extract the screenshot from the response
      const { message } = response.data;

      // Update the screenshot state to render in the UI
      setScreenshot(message);
    } catch (err) {
      console.error("Error while submitting the form", err);
      setError("Error: Failed to submit ad. Please try again.");
    } finally {
      setLoading(false); // Stop loading regardless of outcome
    }
  };

  return (
    <div style={{ padding: 20 }}>
      <Typography variant="h4" gutterBottom>
        Publicar Anuncio
      </Typography>

      <form onSubmit={handleSubmit}>
        <TextField
          label="Precio"
          variant="outlined"
          value={price}
          onChange={(e) => setPrice(e.target.value)}
          fullWidth
          margin="normal"
        />

        <TextField
          label="Descripción"
          variant="outlined"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          multiline
          rows={4}
          fullWidth
          margin="normal"
        />

        <Button
          type="submit"
          variant="contained"
          color="primary"
          disabled={loading} // Disable button while loading
          fullWidth
        >
          {loading ? <CircularProgress size={24} /> : "Publicar"}
        </Button>
      </form>

      {/* Show error message if there's an error */}
      {error && <Typography color="error">{error}</Typography>}

      {/* Display the screenshot once it's received */}
      {screenshot && (
        <div style={{ marginTop: 20 }}>
          <Typography variant="h6">Anuncio Publicado</Typography>
          <img src={`data:image/png;base64,${screenshot}`} alt="Anuncio" />
        </div>
      )}
    </div>
  );
};

export default AdForm;
